/**
 * analyze-comment bot — renders the reusable workflow's sticky PR comment
 * from two `yumcss analyze --json` documents (HEAD + base).
 *
 * Usage: node analyze-comment.mjs <head.json> <base.json>
 * Env:   PR_NUMBER, REPO, GH_TOKEN (comment skipped when any is missing),
 *        BASE_REF_NAME (label only).
 *
 * Marker-keyed update-in-place, identical to pr-report.mjs's contract:
 * `<!-- yumcss-analyze-comment -->`.
 *
 * Fail-open by design: reporting problems exit 0 with a warning.
 */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

const MARKER = "<!-- yumcss-analyze-comment -->";

const head = JSON.parse(readFileSync(process.argv[2] ?? "analyze-head.json", "utf8"));
const base = JSON.parse(readFileSync(process.argv[3] ?? "analyze-base.json", "utf8"));

function fmtKb(bytes) {
	return `${(bytes / 1024).toFixed(2)} KB`;
}

function deltaBytes(headBytes, baseBytes) {
	if (!Number.isFinite(headBytes) || !Number.isFinite(baseBytes)) return "n/a";
	const d = headBytes - baseBytes;
	return `${d > 0 ? "+" : ""}${d} B (${d === 0 ? "±0" : `${d > 0 ? "+" : ""}${((d / baseBytes) * 100).toFixed(2)}%`})`;
}

function row(label, value, flagWarn) {
	return `| ${label} | ${flagWarn ? `\`${value}\`` : value} |`;
}

function buildBody() {
	const sections = [];
	sections.push(`${MARKER}`);
	sections.push(`## yumcss analyze (vs \`${process.env.BASE_REF_NAME ?? "base"}\`)`);
	sections.push("| metric | value |");
	sections.push("| --- | --- |");

	sections.push(
		row(
			"cx() fold coverage",
			`${head.eliminatedPct ?? "?"}%${base?.eliminatedPct !== undefined ? ` (base ${base.eliminatedPct}%, ${deltaInt(head.eliminatedPct ?? 0, base.eliminatedPct)}pp)` : ""}`,
			false,
		),
	);
	sections.push(row("tw() calls folded", `${head.twFolded ?? 0}/${head.totalTwCalls ?? 0}`, false));

	const headMissing = head.missingCss?.count ?? 0;
	const baseMissing = base.missingCss?.count;
	sections.push(
		row(
			"missing-CSS tokens",
			baseMissing !== undefined
				? `${headMissing} (base ${baseMissing}, ${deltaInt(headMissing, baseMissing)})`
				: String(headMissing),
			headMissing > 0,
		),
	);

	const hb = head.cssBudget?.cssBytes;
	const bb = base.cssBudget?.cssBytes;
	sections.push(row("css size", Number.isFinite(hb) ? fmtKb(hb) : "n/a", false));
	sections.push(
		row(
			"css size delta",
			deltaBytes(hb, bb),
			Number.isFinite(hb) && Number.isFinite(bb) && hb > bb,
		),
	);
	const hg = head.cssBudget?.cssGzipBytes;
	const bg = base.cssBudget?.cssGzipBytes;
	sections.push(row("css gzip", `${fmtKb(hg)} vs ${fmtKb(bg)}`, false));

	const sites = head.missingCss?.sites ?? [];
	if (sites.length > 0) {
		sections.push("\n<details><summary>missing-CSS sample (first 10)</summary>\n");
		sections.push("| file:line | token |");
		sections.push("| --- | --- |");
		for (const s of sites.slice(0, 10)) sections.push(`| ${s.file}:${s.line} | \`${s.token}\` |`);
		sections.push("\n</details>");
	}
	sections.push(
		"\n_generated by [yumcss analyze](https://github.com/astahmer/yumcss) — updates in place._",
	);
	return sections.join("\n");
}

function deltaInt(headNum, baseNum) {
	const d = headNum - baseNum;
	return `${d > 0 ? "+" : ""}${d}`;
}

function postOrUpdate(body) {
	const { PR_NUMBER, REPO, GH_TOKEN } = process.env;
	if (!PR_NUMBER || !REPO || !GH_TOKEN) {
		warn("PR_NUMBER/REPO/GH_TOKEN missing — comment skipped, report follows:");
		console.log(body);
		return;
	}
	const listed = runGh(
		[
			"api",
			`repos/${REPO}/issues/${PR_NUMBER}/comments`,
			"--jq",
			`.[] | select(.body | startswith("${MARKER}")) | .id`,
		],
		GH_TOKEN,
	);
	const existingId = listed
		.split("\n")
		.map((s) => s.trim())
		.find(Boolean);
	const args = existingId
		? [
				"api",
				"--method",
				"PATCH",
				"-f",
				`body=${body}`,
				`repos/${REPO}/issues/${PR_NUMBER}/comments/${existingId}`,
			]
		: [
				"api",
				"--method",
				"POST",
				"-f",
				`body=${body}`,
				`repos/${REPO}/issues/${PR_NUMBER}/comments`,
			];
	runGh(args, GH_TOKEN);
	console.log("[analyze-comment] comment posted/updated.");
}

function runGh(args, token) {
	return execFileSync("gh", args, {
		env: { ...process.env, GH_TOKEN: token },
		encoding: "utf8",
		stdio: ["ignore", "pipe", "pipe"],
	});
}

function warn(message) {
	console.warn(`[analyze-comment] ${message}`);
}

main()
	.catch((error) => warn(`report skipped entirely: ${error?.message ?? error}`))
	.finally(() => process.exit(0));

function main() {
	postOrUpdate(buildBody());
}
